//! Display width of a code point, as tmux 3.8 computes it (utf8.c
//! `utf8_width`): zero for combining marks and C1 controls, two for wide
//! characters, one for everything else. The tables are generated by
//! `gen_widths.sh`.

include!("widths.in");

fn in_ranges(ranges: &[(u32, u32)], cp: u32) -> bool {
    ranges
        .binary_search_by(|&(lo, hi)| {
            if cp < lo {
                std::cmp::Ordering::Greater
            } else if cp > hi {
                std::cmp::Ordering::Less
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}

/// Width of a character that went through `utf8_open`/`utf8_append`
/// (multi-byte characters).
pub(super) fn char_width(cp: u32) -> u8 {
    if in_ranges(ZERO, cp) {
        0
    } else if in_ranges(WIDE, cp) {
        2
    } else {
        1
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Reference: `bind -T k KEY display` then `list-keys -T k` orders
    /// width-0 characters first (see golden.rs); here the tables themselves.
    #[test]
    fn widths() {
        assert_eq!(char_width(0x80), 0);
        assert_eq!(char_width(0x9f), 0);
        assert_eq!(char_width(0xa0), 1);
        assert_eq!(char_width(0xe9), 1);
        assert_eq!(char_width(0x300), 0);
        assert_eq!(char_width(0x200b), 0); // glibc wcwidth: zero width space
        assert_eq!(char_width(0x65e5), 2); // 日
        assert_eq!(char_width(0x1f600), 2); // 😀
        assert_eq!(char_width(0x1f1e6), 1); // tmux's own cache: regional indicator
    }
}
